def now_iso(): return datetime.now(timezone.utc).isoformat().replace('+00:00','Z')
def read_json(p:Path,d:Any):
    try: return json.loads(p.read_text(encoding='utf-8'))
    except Exception: return d
def write_json(p:Path,d:Any): p.parent.mkdir(parents=True,exist_ok=True); p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def cache_entries():
    c=read_json(DETAIL_CACHE,{})
    return len(c) if isinstance(c,dict) else 0
def python_bin(): return str(VENV_PYTHON) if VENV_PYTHON.exists() else 'python3'
def python_env():
    env=os.environ.copy()
    if VENV_PYTHON.exists():
        env['PATH']=f"{VENV_PYTHON.parent}:{env.get('PATH','')}"; sites=sorted((ROOT/'.venv'/'lib').glob('python*/site-packages'))
        if sites: env['PYTHONPATH']=':'.join([str(p) for p in sites]+([env.get('PYTHONPATH','')] if env.get('PYTHONPATH') else []))
    return env
def run_step(step_id, script, timeout, cont=False, extra=None):
    cmd=[python_bin(), str(SCRIPTS/script), *(extra or [])]; started=now_iso()
    try:
        proc=oss_process.run(cmd,cwd=str(SCRIPTS),env=python_env(),capture_output=True,text=True,timeout=timeout)
        row={'stepId':step_id,'command':cmd,'startedAt':started,'finishedAt':now_iso(),'returncode':proc.returncode,'ok':proc.returncode==0,'stdoutTail':(proc.stdout or '')[-6000:],'stderrTail':(proc.stderr or '')[-6000:]}
        if proc.returncode!=0 and not cont: row['fatal']=True
        return row
    except subprocess.TimeoutExpired as exc:
        row={'stepId':step_id,'command':cmd,'startedAt':started,'finishedAt':now_iso(),'returncode':None,'ok':False,'timeout':True,'stdoutTail':((exc.stdout or '') if isinstance(exc.stdout,str) else '')[-6000:],'stderrTail':((exc.stderr or '') if isinstance(exc.stderr,str) else '')[-6000:]}
        if not cont: row['fatal']=True
        return row
    except Exception as exc:
        row={'stepId':step_id,'command':cmd,'startedAt':started,'finishedAt':now_iso(),'returncode':None,'ok':False,'exception':str(exc)}
        if not cont: row['fatal']=True
        return row
def compact(path:Path):
    p=read_json(path,{})
    if not isinstance(p,dict): return {'exists':path.exists()}
    return {'exists':path.exists(),'ok':p.get('ok'),'status':p.get('status'),'summary':p.get('summary'),'counts':p.get('counts'),'blockingReasons':p.get('blockingReasons'),'generatedAt':p.get('generatedAt'),'rulesVersion':p.get('rulesVersion')}
def as_int(data:dict[str,Any], key:str, default:int=0) -> int:
    if not isinstance(data, dict): return default
    value=data.get(key)
    return int(value) if value is not None else default
def close_readiness_fresh(max_age_seconds=3600):
    report=read_json(CLOSE_READINESS_REPORT,{})
    if not isinstance(report,dict) or report.get('ok') is not True: return False
    try:
        stamp=datetime.fromisoformat(str(report.get('generatedAt','')).replace('Z','+00:00'))
        age=(datetime.now(timezone.utc)-stamp).total_seconds()
        return 0 <= age <= max_age_seconds
    except Exception:
        return False


def artifact_from_cycle(artifact, cycle_started):
    try:
        stamp=datetime.fromisoformat(str(artifact.get('generatedAt','')).replace('Z','+00:00'))
        start=datetime.fromisoformat(str(cycle_started).replace('Z','+00:00'))
        return start <= stamp <= datetime.now(timezone.utc)
    except (ValueError, TypeError, AttributeError):
        return False

def completion_for_cycle(terminal_state, steps, cycle_started):
    terminal_steps=('inqom-terminal-execution-state-guardrail','inqom-terminal-execution-state-guardrail-tests')
    fresh=artifact_from_cycle(terminal_state,cycle_started)
    completed=all(any(s.get('stepId')==name and s.get('ok') is True for s in steps) for name in terminal_steps)
    if any(s.get('fatal') for s in steps) or not fresh or not completed:
        return 'blocked_incomplete_work', 'unknown', fresh
    semantics=terminal_state.get('stateSemantics') or {}
    return semantics.get('businessCompletionStatus','blocked_incomplete_work'), semantics.get('safetyStatus','unknown'), fresh


